import { useEffect, useState } from 'react';
import {
  AccessibilityInfo,
  Animated,
  AppState,
  type AppStateStatus,
  Image,
  Pressable,
  StyleSheet,
  Text,
  View,
} from 'react-native';
import { FINNI_ANCHORS, FINNI_CANVAS, FINNI_STAGE_SCALE, type FinniExpression, type FinniStage } from './finni-layer-contract.ts';

import { homePetFrame, type SceneRect } from './home-scene-layout.ts';
import { FINNI_APPEARANCE_ASSETS } from './finni-appearance-assets.ts';
import { homeFinniAppearance, type FinniAppearance } from './finni-appearance-policy.ts';
import { FINNI_EXPRESSION_ASSETS } from './finni-expression-assets.ts';

const ROOM_SOURCE = require('../../assets/2d/master/FINNI-2D-MASTER-V1/room_clean_v1.png');

const IDLE_DURATION_MS = 3600;
const BLINK_FRAME_MS = 140;
const BLINK_CYCLE_FRAMES = 24;
const REACTION_HOLD_MS = 2500;

export type HomeReaction = Readonly<{ id: number; expression: Extract<FinniExpression, 'happy' | 'thoughtful' | 'inspired'>; skippable: boolean }>;

export default function FinniHomeScene(props: Readonly<{
  accessibilityLabel: string;
  careLabel: string;
  height: number;
  paused: boolean;
  motionEnabled: boolean;
  stage: FinniStage;
  appearance: FinniAppearance;
  reaction?: HomeReaction | null;
  onReactionFinished?: (id: number) => void;
  onReactionCancelled?: (id: number) => void;
  showCaption?: boolean;
  fullscreen?: boolean;
  petRegion?: SceneRect;
  hideSkip?: boolean;
  skipReactionId?: number | null;
}>) {
  const { reaction, onReactionFinished, onReactionCancelled } = props;
  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState);
  const [reduceMotion, setReduceMotion] = useState(false);
  const [blinkPhase, setBlinkPhase] = useState(0);
  const [decodeError, setDecodeError] = useState(false);
  const [loadedBlinkAppearance, setLoadedBlinkAppearance] = useState<string | null>(null);
  const [loadedExpression, setLoadedExpression] = useState<string | null>(null);
  const [skippedReaction, setSkippedReaction] = useState<number | null>(null);
  const [translateY] = useState(() => new Animated.Value(0));
  const [expressionOpacity] = useState(() => new Animated.Value(0));
  const motionActive = appState === 'active' && !props.paused && props.motionEnabled && !reduceMotion && !decodeError;
  const animationActive = motionActive && !reaction && !props.accessibilityLabel.startsWith('QA-');
  const stageScale = FINNI_STAGE_SCALE[props.stage];
  const appearanceId = homeFinniAppearance(props.appearance);
  const sources = FINNI_APPEARANCE_ASSETS[appearanceId];
  const expressionKey = reaction ? `${appearanceId}/${reaction.expression}/${reaction.id}` : null;
  const expressionReady = expressionKey !== null && loadedExpression === expressionKey;
  const showBlink = animationActive && loadedBlinkAppearance === appearanceId
    && blinkPhase === BLINK_CYCLE_FRAMES - 1;
  const petFrame = props.petRegion ? homePetFrame(props.petRegion, props.stage) : {
    width: `${stageScale * 100}%` as const,
    height: `${stageScale * 100}%` as const,
    left: `${(1 - stageScale) * FINNI_ANCHORS.feet.x / FINNI_CANVAS.width * 100}%` as const,
    top: `${(1 - stageScale) * FINNI_ANCHORS.feet.y / FINNI_CANVAS.height * 100}%` as const,
  };

  const petMotion = props.petRegion ? { transformOrigin: [FINNI_ANCHORS.feet.x * (petFrame as ReturnType<typeof homePetFrame>).scale, FINNI_ANCHORS.feet.y * (petFrame as ReturnType<typeof homePetFrame>).scale, 0], transform: [{ scaleY: translateY.interpolate({ inputRange: [-4, 0], outputRange: [1.006, 1] }) }] } : { transform: [{ translateY }] };

  useEffect(() => {
    void AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
    const appStateSubscription = AppState.addEventListener('change', setAppState);
    const motionSubscription = AccessibilityInfo.addEventListener(
      'reduceMotionChanged',
      setReduceMotion,
    );
    return () => {
      appStateSubscription.remove();
      motionSubscription.remove();
    };
  }, []);

  useEffect(() => {
    if (!animationActive) {
      translateY.stopAnimation();
      translateY.setValue(0);
      return;
    }

    const idle = Animated.loop(
      Animated.sequence([
        Animated.timing(translateY, {
          duration: IDLE_DURATION_MS / 2,
          toValue: -4,
          useNativeDriver: true,
        }),
        Animated.timing(translateY, {
          duration: IDLE_DURATION_MS / 2,
          toValue: 0,
          useNativeDriver: true,
        }),
      ]),
    );
    const blinkTimer = setInterval(() => {
      setBlinkPhase((value) => (value + 1) % BLINK_CYCLE_FRAMES);
    }, BLINK_FRAME_MS);
    idle.start();

    return () => {
      idle.stop();
      clearInterval(blinkTimer);
      translateY.setValue(0);
    };
  }, [animationActive, translateY]);

  useEffect(() => {
    expressionOpacity.stopAnimation();
    if (!expressionReady) {
      expressionOpacity.setValue(0);
      return;
    }
    if (!motionActive || (skippedReaction === reaction?.id || props.skipReactionId === reaction?.id)) {
      console.info('S9QA static-expression', motionActive, props.skipReactionId); expressionOpacity.setValue(1);
      return;
    }
    console.info('S9QA transition', reaction?.expression); expressionOpacity.setValue(0);
    const transition = Animated.timing(expressionOpacity, { duration: reaction?.skippable ? 900 : 140, toValue: 1, useNativeDriver: true });
    transition.start();
    return () => transition.stop();
  }, [expressionOpacity, expressionKey, expressionReady, motionActive, reaction, skippedReaction, props.skipReactionId]);

  useEffect(() => {
    if (!reaction) return;
    const id = reaction.id;
    if (props.paused || appState !== 'active' || decodeError) {
      onReactionCancelled?.(id);
      return;
    }
    if (!expressionReady) return;
    const timer = setTimeout(() => onReactionFinished?.(id), REACTION_HOLD_MS);
    return () => clearTimeout(timer);
  }, [appState, decodeError, expressionReady, onReactionCancelled, onReactionFinished, props.paused, reaction]);

  useEffect(() => {
    if (!reaction) return;
    const id = reaction.id;
    return () => onReactionCancelled?.(id);
  }, [onReactionCancelled, reaction]);

  if (decodeError) {
    return (
      <View
        accessible
        accessibilityLabel={`${props.accessibilityLabel}. Изображение недоступно, показан безопасный локальный вариант.`}
        style={[styles.fallback, props.petRegion ? { position: "absolute", left: props.petRegion.x, top: props.petRegion.y, width: props.petRegion.width, height: props.petRegion.height, padding: 2, justifyContent: "center" } : { height: props.height }]}
        testID="finni-home-scene-fallback"
      >
        <Text style={[styles.fallbackTitle, props.fullscreen && styles.fullscreenFallbackTitle]}>Финни рядом</Text>
        {!props.fullscreen && <Text style={styles.fallbackText}>{props.careLabel}</Text>}
      </View>
    );
  }

  return (
    <View
      accessible={false}
      style={[styles.scene, props.fullscreen && { borderRadius: 0 }, { height: props.height }]}
      testID="finni-home-scene"
    >
      <Image
        accessibilityIgnoresInvertColors
        onError={() => { console.info('S9QA decode-error'); setDecodeError(true); }}
        resizeMode="cover"
        source={props.accessibilityLabel.startsWith('QA-missing') ? { uri: 'file:///data/data/com.meshnavigator.finni/files/missing-room.png' } : props.accessibilityLabel.startsWith('QA-corrupt') ? { uri: 'file:///data/data/com.meshnavigator.finni/files/corrupt-room.png' } : ROOM_SOURCE}
        style={styles.layer}
      />
      <Animated.Image
        key={`${appearanceId}-neutral`}
        accessible={!props.fullscreen}
        accessibilityLabel={props.accessibilityLabel}
        accessibilityIgnoresInvertColors
        fadeDuration={0}
        onError={() => { console.info('S9QA decode-error'); setDecodeError(true); }}
        resizeMode="contain"
        source={sources.neutral}
        style={[styles.petLayer, petFrame, { opacity: showBlink ? 0 : 1, ...petMotion }]}
      />
      <Animated.Image
        key={`${appearanceId}-blink`}
        accessibilityIgnoresInvertColors
        fadeDuration={0}
        onError={() => { console.info('S9QA decode-error'); setDecodeError(true); }}
        onLoad={() => setLoadedBlinkAppearance(appearanceId)}
        resizeMode="contain"
        source={sources.blink}
        style={[styles.petLayer, petFrame, { opacity: showBlink ? 1 : 0, ...petMotion }]}
      />
      {reaction && (
        <Animated.Image
          key={expressionKey}
          accessibilityIgnoresInvertColors
          fadeDuration={0}
          onError={() => { console.info('S9QA decode-error'); setDecodeError(true); }}
          onLoad={() => { console.info('S9QA expression-loaded', reaction.expression); setLoadedExpression(expressionKey); }}
          resizeMode="contain"
          source={FINNI_EXPRESSION_ASSETS[appearanceId][reaction.expression]}
          style={[styles.petLayer, petFrame, { opacity: expressionReady ? expressionOpacity : 0 }]}
          testID={`finni-expression-${reaction.expression}`}
        />
      )}
      {!props.hideSkip && reaction?.skippable && skippedReaction !== reaction.id && motionActive && (
        <Pressable accessibilityRole="button" onPress={() => setSkippedReaction(reaction!.id)} style={styles.skip} testID="finni-reaction-skip">
          <Text style={styles.skipText}>Пропустить анимацию</Text>
        </Pressable>
      )}
      {props.showCaption !== false && (
        <View pointerEvents="none" style={styles.caption}>
          <Text style={styles.captionTitle}>Финни дома</Text>
          <Text style={styles.captionText}>{props.careLabel}</Text>
        </View>
      )}
    </View>
  );
}

